targets.expr:
sum by (workload) (
  rate(container_cpu_usage_seconds_total{namespace=~"$namespace", container!="", container!="POD", pod=~".+"}[$__rate_interval])
  * on (namespace, pod) group_left(workload) (
    label_replace(kube_pod_owner{namespace=~"$namespace", owner_kind="ReplicaSet"}, "workload", "$1", "owner_name", "^(.+)-[^-]+$") or label_replace(kube_pod_owner{namespace=~"$namespace", owner_kind!="ReplicaSet"}, "workload", "$1", "owner_name", "^(.+)$")
  )
)

